<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$labels=['live'=>'Canal en vivo','movie'=>'Película','episode'=>'Episodio'];?>
<div class="space-y-5" x-data x-init="setTimeout(()=>{if(!document.hidden)location.reload()},20000)"><header><h1 class="text-3xl font-bold">Conexiones activas</h1><p class="text-slate-400 mt-1">País, línea, contenido y servidor en tiempo real. Actualiza cada 20 segundos.</p></header>
<section class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3"><?php foreach([['Conexiones',$summary['connections']??0,'text-cyan-400'],['Usuarios',$summary['users']??0,'text-emerald-400'],['Canales',$summary['live']??0,'text-blue-400'],['Películas',$summary['movies']??0,'text-violet-400'],['Episodios',$summary['episodes']??0,'text-fuchsia-400'],['Países',$summary['countries']??0,'text-amber-400']] as [$l,$v,$c]):?><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500 uppercase"><?=$l?></span><strong class="block text-2xl <?=$c?>"><?=number_format((int)$v)?></strong></div><?php endforeach?></section>
<form class="grid md:grid-cols-4 gap-3 bg-slate-900 border border-slate-800 rounded-xl p-4"><input name="q" value="<?=$e($filters['q'])?>" placeholder="Línea, contenido o IP" class="bg-slate-800 p-2 rounded"><select name="type" class="bg-slate-800 p-2 rounded"><option value="">Todo el contenido</option><?php foreach($labels as $v=>$l):?><option value="<?=$v?>" <?=$filters['type']===$v?'selected':''?>><?=$l?></option><?php endforeach?></select><select name="country" class="bg-slate-800 p-2 rounded"><option value="">Todos los países</option><?php foreach($countries as $c):?><option value="<?=$e($c['country'])?>" <?=$filters['country']===$c['country']?'selected':''?>><?=$e($c['country'])?> (<?=$c['total']?>)</option><?php endforeach?></select><div class="flex gap-2"><button class="flex-1 bg-cyan-700 rounded">Filtrar</button><a href="/sessions" class="bg-slate-700 rounded px-4 grid place-items-center">×</a></div></form>
<div class="overflow-x-auto border border-slate-800 rounded-xl"><table class="w-full min-w-[1200px] text-sm"><thead class="bg-slate-900 text-slate-400"><tr><th class="p-3 text-left">Línea</th><th>País / IP</th><th class="text-left">Contenido</th><th>Servidor</th><th>Inicio</th><th>Última señal</th><th class="p-3 text-right">Control</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($sessions as $s):?><tr class="hover:bg-slate-900/50"><td class="p-3"><strong><?=$e($s['username'])?></strong><div class="text-xs space-x-1"><?php if($s['is_trial']):?><span class="text-fuchsia-400">TRIAL</span><?php endif?><?php if($s['is_restreamer']):?><span class="text-orange-400">RESTREAMER</span><?php endif?></div></td><td class="text-center"><span class="inline-block bg-slate-800 rounded px-2 py-1 font-bold"><?=$e($s['country']?:'??')?></span><div class="text-xs text-slate-500 mt-1"><?=$e($s['ip'])?></div></td><td><strong><?=$e($s['content_title']?:'Sin identificar')?></strong><div class="text-xs text-slate-500"><?=$e($labels[$s['content_type']]??$s['content_type']??'')?></div></td><td class="text-center"><?=$e($s['server_name']?:'Principal')?></td><td class="text-center"><?=$e($s['started_at'])?></td><td class="text-center"><?=$e($s['last_seen_at'])?></td><td class="p-3"><div class="flex justify-end gap-1"><form method="post" action="/sessions/disconnect" onsubmit="return confirm('¿Terminar esta reproducción?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$e($s['id'])?>"><button class="bg-red-800 px-2 py-1 rounded">Terminar</button></form><?php if($s['content_item_id']):?><form method="post" action="/sessions/kill-content" onsubmit="return confirm('¿Terminar TODAS las reproducciones de este contenido?')"><?=$csrf->field()?><input type="hidden" name="content_id" value="<?=$s['content_item_id']?>"><button class="bg-violet-800 px-2 py-1 rounded">Kill stream</button></form><?php endif?><form method="post" action="/sessions/ban-line" onsubmit="return confirm('¿Bloquear esta línea y desconectarla?')"><?=$csrf->field()?><input type="hidden" name="account_id" value="<?=$s['account_id']?>"><button class="bg-amber-800 px-2 py-1 rounded">Ban línea</button></form><form method="post" action="/sessions/ban-ip" onsubmit="return confirm('¿Bloquear esta IP y terminar todas sus conexiones?')"><?=$csrf->field()?><input type="hidden" name="ip" value="<?=$e($s['ip'])?>"><button class="bg-slate-700 px-2 py-1 rounded">Ban IP</button></form></div></td></tr><?php endforeach?><?php if(!$sessions):?><tr><td colspan="7" class="p-12 text-center text-slate-500">No hay conexiones activas con estos filtros.</td></tr><?php endif?></tbody></table></div></div>
